using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OmenReward", menuName = "Data/Rewards/OmenReward", order = 0)]
public class OmenReward : Reward
{
	[Header("Omen Reward")]
	[SerializeField]
	private OmenTier omenTier;

	[SerializeField]
	private OmensListsList omensListsList;

	[SerializeField]
	private ListOmenDataEvent OnOmenRewardsGenerated;

	[SerializeField]
	private PlayerCurrentOmens playerCurrentOmens;

	[SerializeField]
	private int omenRewardAmount;

	[SerializeField]
	private GameObject omenRewardPanelPrefab;

	[SerializeField]
	private GameObjectReference omenRewardPanelReference;

	[SerializeField]
	private GameObjectReference telescopeRewardPropGameObjectReference;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private bool nonSkippableOmen;

	[SerializeField]
	[ShowIf("nonSkippableOmen")]
	private VoidEvent OnNonSkippableOmen;

	[SerializeField]
	private bool specificOmenReward;

	[SerializeField]
	[ShowIf("specificOmenReward")]
	private OmenData specificOmenDataReward;

	[SerializeField]
	[ShowIf("specificOmenReward")]
	private bool dontUseOmenRewardPanel;

	[SerializeField]
	[ShowIf("dontUseOmenRewardPanel")]
	private OmenDataEvent OnOmenRewardChosenEvent;

	[SerializeField]
	private bool enableSpecificOmenRewardList;

	[SerializeField]
	[ShowIf("enableSpecificOmenRewardList")]
	private List<OmenData> specificOmenRewardList = new List<OmenData>();

	[SerializeField]
	private bool meissaBattle;

	[NonSerialized]
	public List<OmenData> JustShuffledOmenData = new List<OmenData>();

	public override string GetRewardName()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(rewardName);
	}

	public override void GetReward()
	{
		if (specificOmenReward)
		{
			if (dontUseOmenRewardPanel)
			{
				OnOmenRewardChosenEvent.Raise(specificOmenDataReward);
				omensListsList.BlessingDiscovered(specificOmenDataReward);
				return;
			}
			CheckIfOmenRewardsPanelSpawned();
			List<OmenData> list = new List<OmenData>();
			list.Add(specificOmenDataReward);
			if (nonSkippableOmen)
			{
				OnNonSkippableOmen.Raise();
			}
			OnOmenRewardsGenerated.Raise(list);
			return;
		}
		if (enableSpecificOmenRewardList)
		{
			CheckJustShuffledOmen();
			CheckIfOmenRewardsPanelSpawned();
			List<OmenData> list2 = new List<OmenData>();
			list2.AddRange(specificOmenRewardList);
			if (meissaBattle)
			{
				list2.InsertRange(1, GetOmens(1));
			}
			OnOmenRewardsGenerated.Raise(list2);
			return;
		}
		CheckJustShuffledOmen();
		Action omenRewardGeneratedAction = delegate
		{
			CheckIfOmenRewardsPanelSpawned();
			List<OmenData> omens = GetOmens(omenRewardAmount);
			OnOmenRewardsGenerated.Raise(omens);
			JustShuffledOmenData = omens;
			if (nonSkippableOmen)
			{
				OnNonSkippableOmen.Raise();
			}
		};
		if (JustShuffledOmenData.Count == 0)
		{
			float num = 0.2f;
			InvokeAlternatives.Invoke(delay: (!telescopeRewardPropGameObjectReference.value) ? num : ((!telescopeRewardPropGameObjectReference.value.activeInHierarchy) ? num : ((!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation) ? 3.8f : num)), starterScript: ReferenceSingleton<CoroutineHandler>.Instance, action: delegate
			{
				omenRewardGeneratedAction();
			});
		}
		else
		{
			omenRewardGeneratedAction();
		}
	}

	private void CheckIfOmenRewardsPanelSpawned()
	{
		if (omenRewardPanelReference.value == null)
		{
			omenRewardPanelReference.value = UnityEngine.Object.Instantiate(omenRewardPanelPrefab);
			omenRewardPanelReference.value.GetComponent<Canvas>().worldCamera = Camera.main;
		}
	}

	private void SetSeed()
	{
		if (JustShuffledOmenData.Count == 0)
		{
			RandomUtilities.SetUnityEngineRandomInitStateSeed(mapHandler.GetSeedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount());
		}
	}

	private void CheckJustShuffledOmen()
	{
		if (omenRewardPanelReference.value == null)
		{
			JustShuffledOmenData.Clear();
		}
	}

	public List<OmenData> GetOmens(int omensAmount)
	{
		SetSeed();
		OmenTier replaceBlessingsRunModifierOmenTier = omenTier;
		if (ReferenceSingleton<RunModifiersManager>.Instance.ReplaceBlessingsRunModifierOmenTier != null)
		{
			replaceBlessingsRunModifierOmenTier = ReferenceSingleton<RunModifiersManager>.Instance.ReplaceBlessingsRunModifierOmenTier;
		}
		List<OmenData> list = omensListsList.GetCurrentCharacterUnlockedOmenTierOmenDataList(replaceBlessingsRunModifierOmenTier).omenDatas.Duplicate();
		for (int i = 0; i < playerCurrentOmens.RuntimeOmens.Count; i++)
		{
			list.Remove(playerCurrentOmens.RuntimeOmens[i].OmenData);
		}
		if (list.Count > 3)
		{
			for (int j = 0; j < JustShuffledOmenData.Count; j++)
			{
				list.Remove(JustShuffledOmenData[j]);
			}
		}
		list.RemoveAll((OmenData omen) => (mapHandler.IsOnAstreasHeart && omen.ChapterMute.Contains(3)) || omen.ChapterMute.Contains(mapHandler.CurrentAreaIndex + 1));
		for (int k = 0; k < list.Count; k++)
		{
			if (list[k] is ArtisanStaffOmenData && ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.RuntimeCompanions.Count == 0)
			{
				list.Remove(list[k]);
				break;
			}
		}
		for (int num = list.Count - 1; num >= 0; num--)
		{
			if (list[num] is OnNewRuneOmenData)
			{
				OnNewRuneOmenData onNewRuneOmenData = list[num] as OnNewRuneOmenData;
				if (!onNewRuneOmenData.AddRune && !onNewRuneOmenData.ReplaceAllRunes)
				{
					if (onNewRuneOmenData.GetSpecificRuneIndex() == -1)
					{
						list.Remove(onNewRuneOmenData);
					}
				}
				else if (onNewRuneOmenData.AddRune && onNewRuneOmenData.GetEmptyIndex() == -1)
				{
					list.Remove(onNewRuneOmenData);
				}
			}
		}
		JustShuffledOmenData.Clear();
		if (list.Count < 3)
		{
			return list;
		}
		if (replaceBlessingsRunModifierOmenTier.Boss && omensAmount == 3 && ReferenceSingleton<RunModifiersManager>.Instance.DicelessAnomalyRunModifierAction == null)
		{
			List<OmenData> list2 = new List<OmenData>();
			List<OmenData> list3 = new List<OmenData>();
			for (int l = 0; l < list.Count; l++)
			{
				if (list[l].DrawAdditionalDieOmen)
				{
					list3.Add(list[l]);
				}
			}
			if (list3.Count > 0)
			{
				OmenData item = list3.PickRandom();
				list.Remove(item);
				list2.Add(item);
				list2.AddRange(list.PopRandom(omensAmount - 1));
				return list2;
			}
		}
		return list.PopRandom(omensAmount);
	}
}
